import type { River, RouteSafetyProfile, SourceProvider } from '../../lib/types';

const waterTrailUrl = 'https://paddle607.com/itineraries/sidney-general-clinton-park';
const waterTrailMapUrl = 'https://map.paddle607.com/?l=General+Clinton+Park&lID=3707&zoom=14';
const decSusquehannaUrl = 'https://dec.ny.gov/places/susquehanna-river';
const decNavigationUrl = 'https://dec.ny.gov/outdoor/118441.html';
const usgsDetailUrl = 'https://waterdata.usgs.gov/monitoring-location/USGS-01502632/';
const usgsHydrographUrl = 'https://waterdata.usgs.gov/nwis/uv/?referred_module=sw&site_no=01502632';
const contextImageUrl = 'https://commons.wikimedia.org/wiki/File:Susquehanna_River_at_Laceyville.jpg';

const riverConditionsUrl = 'https://paddle607.com/safety/river-conditions';
const waterTrailSafetyUrl = 'https://paddle607.com/safety/checklist';
const susquehannaRiverName = 'Susquehanna River';

type AdditionalRouteSpec = {
  id: string;
  riverId?: string;
  riverName?: string;
  contextImageUrl?: string;
  reach: string;
  aliases: string[];
  region: string;
  pageUrl: string;
  pageMapUrl: string;
  gaugeSiteId: string;
  gaugeSiteName: string;
  gaugeMetric?: River['gaugeSource']['metric'];
  gaugeUnit?: River['gaugeSource']['unit'];
  runnableMin?: number;
  runnableMax?: number;
  thresholdModel?: River['profile']['thresholdModel'];
  thresholdPageUrl: string;
  thresholdLabel: string;
  distanceMiles: number;
  distanceLabel: string;
  paddleTime: string;
  summary: string;
  statusText: string;
  latitude: number;
  longitude: number;
  putIn: { name: string; latitude: number; longitude: number };
  takeOut: { name: string; latitude: number; longitude: number };
  accessPoints: {
    id: string;
    name: string;
    latitude: number;
    longitude: number;
    mileFromStart: number;
    note: string;
  }[];
  hazards: RouteSafetyProfile['hazards'];
  safetyNotes: string[];
  shuttle: string;
  camping: string;
  campingClassification: 'none' | 'nearby_basecamp' | 'endpoint_campground';
  permits?: string;
  accessCaveats: string[];
  watchFor: string[];
  evidenceNotes: { label: string; value: string; note: string; sourceUrl: string }[];
  difficulty?: 'easy' | 'moderate' | 'hard';
  sourceLabel?: string;
  sourceMapLabel?: string;
  sourceProvider?: SourceProvider;
  routeType?: River['routeType'];
  gaugeKind?: River['gaugeSource']['kind'];
  scoreEligibility?: River['scoreEligibility'];
  gaugeStatusNote?: string;
  riskLevel?: RouteSafetyProfile['riskLevel'];
  difficultyNotes?: string;
  confidenceNotes?: string;
  conditionsUrl?: string;
  conditionsLabel?: string;
  safetyUrl?: string;
  safetyLabel?: string;
  seasonMonths?: number[];
  seasonNotes?: string;
};

function buildAdditionalNewYorkRoute(spec: AdditionalRouteSpec): River {
  const usgsDetailUrl = `https://waterdata.usgs.gov/monitoring-location/USGS-${spec.gaugeSiteId}/`;
  const usgsHydrographUrl = `https://waterdata.usgs.gov/nwis/uv/?referred_module=sw&site_no=${spec.gaugeSiteId}`;
  const sourceLabel = spec.sourceLabel ?? 'NY Susquehanna Basin Water Trail';
  const sourceMapLabel = spec.sourceMapLabel ?? `${sourceLabel} map pins`;
  const sourceProvider = spec.sourceProvider ?? 'local';
  const conditionsUrl = spec.conditionsUrl ?? riverConditionsUrl;
  const conditionsLabel = spec.conditionsLabel ?? `${sourceLabel} river conditions`;
  const safetyUrl = spec.safetyUrl ?? waterTrailSafetyUrl;
  const safetyLabel = spec.safetyLabel ?? `${sourceLabel} safety checklist`;
  const gaugeStatusNote = spec.gaugeStatusNote ?? (spec.gaugeKind === 'proxy'
    ? 'USGS provides continuous telemetry at a same-river downstream proxy; local rainfall, tributary inflow, and dam operations can make route conditions diverge.'
    : 'USGS provides continuous stage and discharge telemetry for the route corridor.');

  return {
    id: spec.id,
    riverId: spec.riverId ?? 'susquehanna-river',
    slug: spec.id,
    name: spec.riverName ?? susquehannaRiverName,
    reach: spec.reach,
    aliases: spec.aliases,
    state: 'New York',
    region: spec.region,
    routeType: spec.routeType ?? 'recreational',
    summary: spec.summary,
    statusText: spec.statusText,
    latitude: spec.latitude,
    longitude: spec.longitude,
    safetyProfile: {
      riskLevel: spec.riskLevel ?? 'caution',
      hazards: ['fast_rise', 'cold_water', 'private_banks', 'access_uncertain', ...spec.hazards],
      safetyNotes: spec.safetyNotes,
      reviewStatus: 'reviewed',
    },
    gaugeSource: {
      id: `usgs-${spec.gaugeSiteId}`,
      provider: 'usgs',
      siteId: spec.gaugeSiteId,
      metric: spec.gaugeMetric ?? 'discharge_cfs',
      unit: spec.gaugeUnit ?? 'cfs',
      kind: spec.gaugeKind ?? 'direct',
      siteName: spec.gaugeSiteName,
      detailUrl: usgsDetailUrl,
      hydrographUrl: usgsHydrographUrl,
    },
    profile: {
      thresholdModel: spec.thresholdModel ?? 'two-sided',
      ...(spec.thresholdModel === 'minimum-only'
        ? {
            ...(typeof spec.runnableMin === 'number' ? { tooLow: spec.runnableMin, idealMin: spec.runnableMin } : {}),
          }
        : {
            tooLow: spec.runnableMin,
            idealMin: spec.runnableMin,
            idealMax: spec.runnableMax,
            tooHigh: spec.runnableMax,
          }),
      thresholdSource: {
        label: spec.thresholdLabel,
        url: spec.thresholdPageUrl,
        provider: 'local',
      },
      thresholdSourceStrength: 'mixed',
      rainfallSensitivity: 'high',
      seasonMonths: spec.seasonMonths ?? [4, 5, 6, 7, 8, 9, 10],
      seasonNotes: spec.seasonNotes ?? `${sourceLabel} advises checking the live gauge and conditions before every launch. April–October is the most dependable planning season, while spring rises and late-summer low water can change the trip quickly.`,
      difficulty: spec.difficulty ?? 'easy',
      difficultyNotes: spec.difficultyNotes ?? `The published itinerary rates this corridor ${spec.difficulty ?? 'easy'}, but current, bridge structures, islands, shallow gravel, cold water, and changing access conditions remain material hazards.`,
      confidenceNotes: spec.confidenceNotes ?? `High route confidence: ${sourceLabel} publishes or identifies the named endpoint pair, access sequence, mileage, hazards, and access descriptions. ${gaugeStatusNote} Any runnable guidance is planning information, not a safety certification.`,
    },
    putIn: spec.putIn,
    takeOut: spec.takeOut,
    accessPoints: spec.accessPoints.map((accessPoint) => ({ ...accessPoint, segmentKind: 'transition' as const })),
    logistics: {
      distanceLabel: spec.distanceLabel,
      estimatedPaddleTime: spec.paddleTime,
      shuttle: spec.shuttle,
      permits: spec.permits ?? `No route-specific paddling permit is identified by the route source. Follow current New York boating, PFD, DEC access, parking, park, and posted rules; verify any event-day or seasonal restrictions before launching.`,
      camping: spec.camping,
      campingClassification: spec.campingClassification,
      summary: spec.summary,
      accessCaveats: spec.accessCaveats,
      watchFor: spec.watchFor,
    },
    evidenceNotes: spec.evidenceNotes.concat([
      { label: spec.gaugeKind === 'proxy' ? 'Same-river proxy gauge' : 'Direct live gauge', value: `USGS ${spec.gaugeSiteId}, ${spec.gaugeSiteName}`, note: gaugeStatusNote, sourceUrl: usgsHydrographUrl },
      { label: 'Safety and river conditions', value: 'Check live gauge, recent rainfall, trend, debris, bridges, and access conditions before launch', note: `${sourceLabel} and its linked safety material warn that conditions change rapidly and require local inspection.`, sourceUrl: conditionsUrl },
      { label: 'Image decision', value: spec.gaugeKind === 'proxy' ? 'Approved watershed/proxy-gauge context image used for route presentation' : 'Approved same-river context image used for route presentation', note: spec.gaugeKind === 'proxy' ? 'The image is clearly labeled as watershed/proxy-gauge context and does not claim to depict this exact reach.' : 'The image is labeled as river-level context when it depicts the named river elsewhere, not this exact reach.', sourceUrl: spec.contextImageUrl ?? contextImageUrl },
    ]),
    sourceLinks: [
      { label: `${sourceLabel} route record`, url: spec.pageUrl, provider: sourceProvider },
      { label: sourceMapLabel, url: spec.pageMapUrl, provider: sourceProvider },
      { label: conditionsLabel, url: conditionsUrl, provider: sourceProvider },
      { label: safetyLabel, url: safetyUrl, provider: sourceProvider },
      { label: `USGS ${spec.gaugeSiteId} monitoring location`, url: usgsDetailUrl, provider: 'usgs' },
      { label: `USGS ${spec.gaugeSiteId} current conditions`, url: usgsHydrographUrl, provider: 'usgs' },
      { label: `${spec.riverName ?? susquehannaRiverName} context image`, url: spec.contextImageUrl ?? contextImageUrl, provider: 'manual' },
    ],
    scoreEligibility: spec.scoreEligibility ?? (spec.gaugeKind === 'proxy' ? 'planning' : 'scored'),
    scoreEligibilityReason: spec.gaugeKind === 'proxy' ? 'proxy_gauge' : undefined,
  };
}


